package com.shopsphere;import static org.assertj.core.api.Assertions.assertThat;import java.sql.DriverManager;import org.junit.jupiter.api.Test;import org.testcontainers.containers.MySQLContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)class AuthPersistenceContainerTest{@Container static MySQLContainer<?>mysql=new MySQLContainer<>("mysql:8.4");@Test void mysqlIsWritable()throws Exception{try(var c=DriverManager.getConnection(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());var s=c.createStatement()){assertThat(s.execute("CREATE TABLE persistence_probe(id INT PRIMARY KEY)")).isFalse();}}}
